29	/**
30	 * Helper to format the policy denial error.
31	 */
32	export function getPolicyDenialError(
33	  config: Config,
34	  rule?: PolicyRule,
35	): { errorMessage: string; errorType: ToolErrorType } {
36	  const denyMessage = rule?.denyMessage ? ` ${rule.denyMessage}` : '';
37	  return {
38	    errorMessage: `Tool execution denied by policy.${denyMessage}`,
39	    errorType: ToolErrorType.POLICY_VIOLATION,
40	  };
41	}
