43	/**
44	 * Queries the system PolicyEngine to determine tool allowance.
45	 * @returns The PolicyDecision.
46	 * @throws Error if policy requires ASK_USER but the CLI is non-interactive.
47	 */
48	export async function checkPolicy(
49	  toolCall: ValidatingToolCall,
50	  config: Config,
51	): Promise<CheckResult> {
52	  const serverName =
53	    toolCall.tool instanceof DiscoveredMCPTool
54	      ? toolCall.tool.serverName
55	      : undefined;
56	
57	  const result = await config
58	    .getPolicyEngine()
59	    .check(
60	      { name: toolCall.request.name, args: toolCall.request.args },
61	      serverName,
62	    );
63	
64	  const { decision } = result;
65	
66	  /*
67	   * Return the full check result including the rule that matched.
68	   * This is necessary to access metadata like custom deny messages.
69	   */
70	  if (decision === PolicyDecision.ASK_USER) {
71	    if (!config.isInteractive()) {
72	      throw new Error(
73	        `Tool execution for "${
74	          toolCall.tool.displayName || toolCall.tool.name
75	        }" requires user confirmation, which is not supported in non-interactive mode.`,
76	      );
77	    }
78	  }
79	
80	  return {
81	    decision,
82	    rule: result.rule,
83	  };
84	}
